new='''_LINKS = {
    "US/Pacific": "America/Los_Angeles", "US/Eastern": "America/New_York", "US/Central": "America/Chicago",
    "Asia/Calcutta": "Asia/Kolkata", "Asia/Saigon": "Asia/Ho_Chi_Minh", "Europe/Kiev": "Europe/Kyiv",
    "America/Buenos_Aires": "America/Argentina/Buenos_Aires", "Brazil/East": "America/Sao_Paulo",
    "UTC": "Etc/UTC", "GMT": "Etc/UTC",
}
_ZERO = {"CLP", "ISK", "JPY", "KRW", "UGX", "VND"}
_THREE = {"BHD", "JOD", "KWD", "OMR", "TND"}
_LOCALES = {"en-US", "en-GB", "en-IN", "de-DE", "de-CH", "fr-FR", "pt-BR", "es", "ja-JP"}
# locale: (decimal, group, code_before)
_STYLE = {
    "en-US": (".", ",", True), "en-GB": (".", ",", True), "ja-JP": (".", ",", True), "en-IN": (".", ",", True),
    "pt-BR": (",", ".", True), "de-DE": (",", ".", False), "es": (",", ".", False),
    "de-CH": (".", "\\u2019", False), "fr-FR": (",", "\\u202f", False),
}


def _link_targets() -> dict[str, str]:
    out: dict[str, str] = {}
    for path in ("/usr/share/zoneinfo/tzdata.zi", "/usr/share/lib/zoneinfo/tzdata.zi"):
        try:
            with open(path) as f:
                for ln in f:
                    parts = ln.split()
                    if len(parts) == 3 and parts[0] == "L":
                        out[parts[2]] = parts[1]
            break
        except OSError:
            continue
    return out


def _zone(tz: str) -> str:
    tz = tz.strip()
    m = re.fullmatch(r"(?:UTC|GMT)?\\s*([+-\\u2212])(\\d{1,2})(?::?(\\d{2}))?", tz)
    if m:
        hours = int(m.group(2))
        sign = -1 if m.group(1) in "-\\u2212" else 1
        if hours == 0:
            return "Etc/UTC"
        return f"Etc/GMT{'-' if sign > 0 else '+'}{hours}"
    if tz in _LINKS:
        return _LINKS[tz]
    if "/" not in tz or tz.startswith(("US/", "Brazil/")):
        t = _link_targets().get(tz)
        if t:
            return t
    else:
        t = _link_targets().get(tz)
        if t:
            return t
    return tz


def _locale(raw: str) -> str:
    base = re.split(r"[.@]", raw)[0].replace("_", "-")
    parts = base.split("-")
    lang = parts[0].lower()
    tag = lang + ("-" + parts[1].upper() if len(parts) > 1 and parts[1] else "")
    if tag in _LOCALES:
        return tag
    if lang in _LOCALES:
        return lang
    return "en-US"


def _digits(currency: str) -> int:
    return 0 if currency in _ZERO else 3 if currency in _THREE else 2


def _amount(value: str, digits: int) -> Decimal:
    return Decimal(value).quantize(Decimal(1).scaleb(-digits), rounding=ROUND_HALF_EVEN)


def _format(value: Decimal, currency: str, locale: str) -> str:
    dec, grp, before = _STYLE[locale]
    digits = _digits(currency)
    neg = value < 0
    text = f"{abs(value):.{digits}f}"
    ipart, _, frac = text.partition(".")
    if locale == "en-IN":
        if len(ipart) > 3:
            head, tail = ipart[:-3], ipart[-3:]
            groups = []
            while len(head) > 2:
                groups.insert(0, head[-2:])
                head = head[:-2]
            if head:
                groups.insert(0, head)
            ipart = grp.join(groups + [tail])
    elif not (locale == "es" and len(ipart) == 4):
        groups = []
        while len(ipart) > 3:
            groups.insert(0, ipart[-3:])
            ipart = ipart[:-3]
        ipart = grp.join([ipart] + groups)
    num = ("-" if neg else "") + ipart + (dec + frac if digits else "")
    return f"{currency}\\u00a0{num}" if before else f"{num}\\u00a0{currency}"


def monthly_statement(transport: Transport, merchant: Merchant, year: int, month: int) -> Statement:
    """The statement of `merchant` for one calendar month, with its days in the merchant's time zone.

    One line per day that has settlements, in day order, with the figures and the text the
    Meridale dashboard shows. Raises ApiError when the API answers with an error.
    """
    first = date(year, month, 1)
    nxt = date(year + month // 12, month % 12 + 1, 1)
    locale = _locale(merchant.locale)
    params = {
        "merchant_id": merchant.id,
        "tz": _zone(merchant.tz),
        "from": first.isoformat(),
        "to": nxt.isoformat(),
        "locale": locale,
    }
    report = _call(transport, "GET", f"{BASE}/settlements", params)
    currency = report["currency"]
    digits = _digits(currency)
    lines = []
    for d in report["days"]:
        gross, fees, refunds = (_amount(d[k], digits) for k in ("gross", "fees", "refunds"))
        net = gross - fees - refunds
        lines.append(Line(date.fromisoformat(d["day"]), gross, fees, refunds, net, _format(net, currency, locale)))
    total = sum((line.net for line in lines), Decimal(0)).quantize(Decimal(1).scaleb(-digits))
    return Statement(merchant.id, currency, tuple(lines), total, _format(total, currency, locale))
'''
s=s[:i]+new
